import{_ as s,o as t,c as i,a3 as n}from"./chunks/framework.DFRwgAh-.js";const m=JSON.parse('{"title":"5 Core Principles of Issue Management","description":"Introducing core principles for using Jira efficiently. ✅ Discover how to increase project transparency and team productivity through issue allocation rules, ✅ essential commenting guides, and ✅ status management know-how. This is a guide for team collaboration.","frontmatter":{"title":"5 Core Principles of Issue Management","description":"Introducing core principles for using Jira efficiently. ✅ Discover how to increase project transparency and team productivity through issue allocation rules, ✅ essential commenting guides, and ✅ status management know-how. This is a guide for team collaboration.","head":[["meta",{"name":"keywords","content":"Jira, Issue Management, How to use Jira, Project Management, Collaboration Tool, Allocation Principles, Commenting, Status Management, Workflow, Productivity Improvement"}],["meta",{"property":"og:title","content":"5 Core Principles of Issue Management | Effective Project Management"}],["meta",{"property":"og:description","content":"Introducing core principles for efficiently using issues. ✅ Discover how to increase project transparency and team productivity through issue allocation rules, ✅ essential commenting guides, and ✅ status management know-how. This is a guide for team collaboration."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://empasy.io/agile/PrinciplesForIssueUsage.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/agile/PrinciplesForIssueUsage.html"}]],"sort":6000},"headers":[],"relativePath":"en/agile/PrinciplesForIssueUsage.md","filePath":"en/agile/PrinciplesForIssueUsage.md","lastUpdated":1787657314000}'),o={name:"en/agile/PrinciplesForIssueUsage.md"};function r(a,e,l,c,g,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="core-principles-for-using-issues-effectively" tabindex="-1">Core Principles for Using Issues Effectively <a class="header-anchor" href="#core-principles-for-using-issues-effectively" aria-label="Permalink to “Core Principles for Using Issues Effectively”">​</a></h2><h3 id="_1-allocation-principles" tabindex="-1">1. <strong>Allocation Principles</strong> <a class="header-anchor" href="#_1-allocation-principles" aria-label="Permalink to “1. Allocation Principles”">​</a></h3><ul><li>✅ <strong>Assign to Current Handler</strong>: An issue must always be assigned to the person who is currently actually working on it.</li><li>✅ <strong>Confirm Upon Allocation</strong>: When an issue is assigned, the assignee must confirm it immediately and state whether they will start working on it.</li><li>❌ <strong>No Empty Allocations</strong>: Issues without an assignee are easily neglected.</li></ul><h3 id="_2-commenting-principles" tabindex="-1">2. <strong>Commenting Principles</strong> <a class="header-anchor" href="#_2-commenting-principles" aria-label="Permalink to “2. Commenting Principles”">​</a></h3><ul><li>✅ <strong>Comment Mandatory Upon Completion</strong>: After completing the work, a comment on the processing result must be added.</li><li>✅ <strong>Share Progress</strong>: Share progress in comments periodically (especially for long-term tasks).</li><li>✅ <strong>Comment Upon Issue Movement</strong>: State the reason for the change when the status changes (e.g., In Progress → Done).</li><li>❌ <strong>No Meaningless Comments</strong>: Do not repeat things like &quot;Checked&quot; or &quot;In progress&quot;.</li></ul><h3 id="_3-status-management-principles" tabindex="-1">3. <strong>Status Management Principles</strong> <a class="header-anchor" href="#_3-status-management-principles" aria-label="Permalink to “3. Status Management Principles”">​</a></h3><ul><li>✅ <strong>Real-time Status Updates</strong>: Immediately update the status according to the current state of work.</li><li>✅ <strong>Clear Status Definitions</strong>: Clearly define the meaning of statuses per team and use them consistently.</li><li>❌ <strong>No Neglected Status</strong>: Do not leave it neglected in the &quot;In Progress&quot; status for a long time.</li></ul><h3 id="_4-issue-writing-principles" tabindex="-1">4. <strong>Issue Writing Principles</strong> <a class="header-anchor" href="#_4-issue-writing-principles" aria-label="Permalink to “4. Issue Writing Principles”">​</a></h3><ul><li>✅ <strong>Clear Title</strong>: Use a title that makes it clear at a glance what needs to be done.</li><li>✅ <strong>Detailed Description</strong>: Describe details including reproduction procedures, expected results, and actual results.</li><li>✅ <strong>Fill Mandatory Fields</strong>: Must fill in mandatory fields such as priority, estimated time required, and components.</li><li>❌ <strong>No Unclear Expressions</strong>: Do not use unclear expressions such as &quot;There is a problem&quot; or &quot;Please fix it&quot;.</li></ul><h3 id="_5-workflow-compliance-principles" tabindex="-1">5. <strong>Workflow Compliance Principles</strong> <a class="header-anchor" href="#_5-workflow-compliance-principles" aria-label="Permalink to “5. Workflow Compliance Principles”">​</a></h3><ul><li>✅ <strong>Follow Defined Workflow</strong>: Strictly comply with the workflow decided by the team.</li><li>✅ <strong>Comply with Review Process</strong>: Do not skip necessary procedures like code reviews and QA processes.</li><li>✅ <strong>Consistent Process</strong>: All team members must work following the same process.</li></ul><h2 id="example-ideal-issue-processing-flow" tabindex="-1">Example: Ideal Issue Processing Flow <a class="header-anchor" href="#example-ideal-issue-processing-flow" aria-label="Permalink to “Example: Ideal Issue Processing Flow”">​</a></h2><ol><li><strong>Create Issue</strong> → Assign handler + Set priority</li><li><strong>Start Work</strong> → Change status to &quot;In Progress&quot; + Start comment</li><li><strong>In Progress</strong> → Write interim progress comments (if necessary)</li><li><strong>Complete Work</strong> → Change status to &quot;Done&quot; + <strong>Detailed processing result comment</strong></li><li><strong>If Review is Needed</strong> → Change status to &quot;Under Review&quot; + Assign reviewer</li></ol>',13)])])}const d=s(o,[["render",r]]);export{m as __pageData,d as default};
